// Package gnofly is the market of gnofly's planes: a fixed-price book where
// a plane's owner lists it, anyone buys it, and each sale pays the planes
// realm's royalty (RoyaltyInfo: 5% to the gnofly treasury) out of the price.
//
// It is a wrapper, not a collection: it mints nothing. The planes are the
// tokens of gno.land/r/g1t2kg2vtr3fukg43eujkn6x53gfdyakhngt4sfd/gnofly/nfts/planes,
// moved with that realm's TransferFrom. A seller first approves this realm
// there (Approve for one plane, or SetApprovalForAll); List then moves the
// plane here, in escrow, Buy hands it to the buyer and Cancel back to the
// seller.
//
// Its calls and reads have the shapes Bazaar's site (bazaar.gnomi.fun)
// uses on a collection package (List, UpdatePrice, Cancel, Buy, Transfer;
// ListOpen, ItemLine, TokensOf, Minted), so that it can be registered there
// later, under the slug of its last path element. It is not registered, and
// pays Bazaar nothing.
//
// It is version v0 of the market (the path's v0). SetPaused stops new
// listings for a move to a newer one; Cancel and Buy keep working, so no
// plane is ever stuck here.
//
// Every write is a direct call from a wallet: no realm can list, buy or
// cancel in a user's name.
package gnofly

package gnofly

import (
	"chain"
	"chain/banker"
	"strconv"

	// Only for OriginSend, in Buy. Caller identity always comes from cur,
	// never from this package.
	"chain/runtime/unsafe"

	"gno.land/p/nt/bptree/v0"
	"gno.land/p/nt/grc721/v0"

	"gno.land/r/g1t2kg2vtr3fukg43eujkn6x53gfdyakhngt4sfd/gnofly/nfts/planes"
)

const (
	payDenom = "ugnot"

	// minPrice keeps the royalty above zero after rounding: 5% of 1 GNOT.
	minPrice = int64(1_000_000)
	// maxPrice keeps price * royalty bps far below an int64.
	maxPrice = int64(1_000_000_000_000)

	supply = 777 // plane ids run from 1 to 777
)

// listing is one plane for sale. The plane itself is held by this realm
// (escrow) until it is bought or the listing is cancelled.
type listing struct {
	seller address
	price  int64 // ugnot
}

var (
	// listings by plane id, as a three-digit key ("042") so that iteration
	// runs in id order.
	listings bptree.BPTree
	// paused stops new listings and price changes, for a move to a newer
	// version of the market. Cancel and Buy keep working: nothing listed here
	// can be stuck.
	paused bool
	// self is this realm's address, recorded at init: what sellers approve
	// on the planes realm.
	self address
)

func init(cur realm) {
	self = cur.Address()
}

// List puts plane id up for sale at priceUgnot. The caller must own it and
// have approved this realm on the planes realm (Approve for this plane, or
// SetApprovalForAll): the plane moves here, in escrow, until it is bought or
// the listing is cancelled.
func List(cur realm, id int, priceUgnot int64) {
	seller := userOf(0, cur)
	if paused {
		panic(errPaused)
	}
	checkPrice(priceUgnot)
	if listings.Has(key(id)) {
		panic(errListed)
	}
	if owner := ownerOf(id); owner != seller {
		panic(errNotOwner)
	}
	if !planes.IsApprovedForAll(seller, self) && planes.GetApproved(int64(id)) != self {
		panic(errNotApproved)
	}
	listings.Set(key(id), &listing{seller: seller, price: priceUgnot})
	planes.TransferFrom(cross(cur), seller, self, int64(id))
	chain.Emit("List", "id", strconv.Itoa(id), "seller", seller.String(), "price", strconv.FormatInt(priceUgnot, 10))
}

// UpdatePrice changes the price of a plane the caller listed.
func UpdatePrice(cur realm, id int, priceUgnot int64) {
	seller := userOf(0, cur)
	if paused {
		panic(errPaused)
	}
	checkPrice(priceUgnot)
	l := mustListing(id)
	if l.seller != seller {
		panic(errNotSeller)
	}
	l.price = priceUgnot
	chain.Emit("UpdatePrice", "id", strconv.Itoa(id), "seller", seller.String(), "price", strconv.FormatInt(priceUgnot, 10))
}

// Cancel takes a listing down and gives the plane back to its seller. It
// works while the market is paused.
func Cancel(cur realm, id int) {
	seller := userOf(0, cur)
	l := mustListing(id)
	if l.seller != seller {
		panic(errNotSeller)
	}
	listings.Remove(key(id))
	planes.TransferFrom(cross(cur), cur.Address(), seller, int64(id))
	chain.Emit("Cancel", "id", strconv.Itoa(id), "seller", seller.String())
}

// Buy buys a listed plane: send exactly its price in ugnot. The royalty of
// the planes realm (RoyaltyInfo: 5% to the gnofly treasury) is paid out of
// the price, the seller receives the rest, and the plane goes to the buyer.
// It works while the market is paused.
func Buy(cur realm, id int) {
	// A direct user call: only then has the -send envelope landed at this
	// realm's address, which the OriginSend banker below pays out of.
	buyer := userOf(0, cur)
	l := mustListing(id)
	if l.seller == buyer {
		panic(errOwnListing)
	}
	sent := unsafe.OriginSend()
	if len(sent) != 1 || sent[0].Denom != payDenom || sent[0].Amount != l.price {
		panic("gnofly market: wrong payment, send exactly " + strconv.FormatInt(l.price, 10) + payDenom)
	}
	// The listing goes before any coin or plane moves.
	listings.Remove(key(id))

	receiver, royalty := planes.RoyaltyInfo(int64(id), l.price)
	if royalty < 0 || royalty > l.price {
		royalty = 0
	}
	bank := banker.NewBanker(banker.BankerTypeOriginSend, cur)
	if royalty > 0 && receiver.IsValid() {
		bank.SendCoins(cur.Address(), receiver, chain.NewCoins(chain.NewCoin(payDenom, royalty)))
	} else {
		royalty = 0
	}
	bank.SendCoins(cur.Address(), l.seller, chain.NewCoins(chain.NewCoin(payDenom, l.price-royalty)))

	planes.TransferFrom(cross(cur), cur.Address(), buyer, int64(id))
	chain.Emit("Buy", "id", strconv.Itoa(id), "seller", l.seller.String(), "buyer", buyer.String(),
		"price", strconv.FormatInt(l.price, 10), "royalty", strconv.FormatInt(royalty, 10))
}

// Transfer gives a plane the caller owns, not listed, to another address,
// through this realm: the call Bazaar's site makes. It needs the same
// approval as List. A plane can always be moved on the planes realm itself.
func Transfer(cur realm, to address, id int) {
	from := userOf(0, cur)
	if !to.IsValid() {
		panic(errBadRecipient)
	}
	if listings.Has(key(id)) {
		panic(errListed)
	}
	if owner := ownerOf(id); owner != from {
		panic(errNotOwner)
	}
	planes.TransferFrom(cross(cur), from, to, int64(id))
	chain.Emit("Transfer", "id", strconv.Itoa(id), "from", from.String(), "to", to.String())
}

// SetPaused stops (or resumes) new listings and price changes. Admin of the
// game realm only. Cancel and Buy keep working, so a move to a newer market
// never strands a plane: sellers cancel here and list there.
func SetPaused(cur realm, p bool) {
	assertAdmin(0, cur)
	paused = p
	chain.Emit("Paused", "paused", strconv.FormatBool(p))
}

// ReturnStray gives back a plane this realm holds outside any listing: one
// someone sent here by mistake. Admin of the game realm only; to is who it
// came from, as the chain's transfer events show.
func ReturnStray(cur realm, id int, to address) {
	assertAdmin(0, cur)
	if !to.IsValid() {
		panic(errBadRecipient)
	}
	if listings.Has(key(id)) || ownerOf(id) != cur.Address() {
		panic(errNotStray)
	}
	planes.TransferFrom(cross(cur), cur.Address(), to, int64(id))
	chain.Emit("ReturnStray", "id", strconv.Itoa(id), "to", to.String())
}

// Paused reports whether new listings are stopped.
func Paused() bool { return paused }

// checkPrice panics unless p is a price this market takes.
func checkPrice(p int64) {
	if p < minPrice || p > maxPrice {
		panic(errBadPrice)
	}
}

// mustListing returns the listing of plane id, or panics.
func mustListing(id int) *listing {
	v := listings.Get(key(id))
	if v == nil {
		panic(errNotListed)
	}
	return v.(*listing)
}

// getListing returns the listing of plane id, or nil.
func getListing(id int) *listing {
	if v := listings.Get(key(id)); v != nil {
		return v.(*listing)
	}
	return nil
}

// ownerOf returns the owner of plane id on the planes realm, or panics for
// an id that is not a minted plane.
func ownerOf(id int) address {
	if id < 1 || id > supply {
		panic(errUnknownPlane)
	}
	owner, err := planes.OwnerOf(tid(id))
	if err != nil {
		panic(errUnknownPlane)
	}
	return owner
}

// key is the listings key of plane id: three digits, "042".
func key(id int) string {
	s := strconv.Itoa(id)
	for len(s) < 3 {
		s = "0" + s
	}
	return s
}

func tid(id int) grc721.TokenID { return grc721.TokenID(strconv.Itoa(id)) }

package gnofly

import (
	"strconv"
	"strings"

	"gno.land/p/nt/grc721/v0"
	"gno.land/p/onbloc/json/v0"

	"gno.land/r/g1t2kg2vtr3fukg43eujkn6x53gfdyakhngt4sfd/gnofly/nfts/planes"
)

// The reads are in the shapes Bazaar's site (bazaar.gnomi.fun) parses on a
// collection package, so that this market can be registered there later
// without a new version. Lines are fields joined by "|":
//
//	id|name|owner|seller|price|listed|image|collection|rarity|traits|revealed|slot
//
// owner is the planes realm's owner, this realm for a listed plane (escrow);
// seller and price are empty and 0 when the plane is not listed. collection
// is the slug Bazaar would know this realm by: the last path element.

// slug is the last element of this realm's path.
const slug = "gnofly"

// maxOpen is the most listings ListOpen returns, as Bazaar's own realms do.
const maxOpen = 50

// Name and Symbol are the planes collection's: the market sells nothing else.
func Name() string   { return "gnofly planes" }
func Symbol() string { return "PLANE" }

// Minted returns how many planes were minted.
func Minted() int { return int(planes.Minted()) }

// OwnerOf returns the owner of a plane on the planes realm: this realm while
// it is listed.
func OwnerOf(tid string) (address, error) {
	return planes.OwnerOf(grc721.TokenID(tid))
}

// TokenURI returns the image of a plane, an https URL.
func TokenURI(tid string) string {
	uri, err := planes.TokenURI(grc721.TokenID(tid))
	if err != nil {
		return ""
	}
	return uri
}

// TokensOf returns the ids of the planes owner holds, comma-separated, in
// id order: "3,42,700". A listed plane is not among them: it is held here.
func TokensOf(owner string) string {
	ids := strings.TrimSuffix(strings.TrimPrefix(planes.PlanesOf(address(owner)), "["), "]")
	return ids
}

// ListOpen returns the listings, one line each, in id order, at most 50.
func ListOpen() string {
	var lines []string
	listings.Iterate("", "", func(k string, v any) bool {
		id, _ := strconv.Atoi(k)
		lines = append(lines, line(id, v.(*listing)))
		return len(lines) >= maxOpen
	})
	return strings.Join(lines, "\n")
}

// ItemLine returns the line of plane id, listed or not. It panics for an id
// that is not a minted plane: Bazaar's site skips the ids it cannot read.
func ItemLine(id int) string {
	ownerOf(id) // panics for an id that is not minted
	return line(id, getListing(id))
}

// line builds the line of plane id; l is its listing, nil when it has none.
func line(id int, l *listing) string {
	p := planeInfo(id)
	owner, _ := planes.OwnerOf(tid(id))
	seller, price, listed := "", "0", "false"
	if l != nil {
		seller, price, listed = l.seller.String(), strconv.FormatInt(l.price, 10), "true"
	}
	traits := "model:" + p.model + ",pilot:" + p.pilot + ",laser:" + p.laser
	return strings.Join([]string{
		strconv.Itoa(id), clean(p.name), owner.String(), seller, price, listed,
		clean(p.image), slug, p.tier, clean(traits), "true", "",
	}, "|")
}

type plane struct {
	name, image, tier, model, pilot, laser string
}

// planeInfo reads plane id from the planes realm's PlaneJSON.
func planeInfo(id int) plane {
	node, err := json.Unmarshal([]byte(planes.PlaneJSON(int64(id))))
	if err != nil {
		panic(errUnknownPlane)
	}
	str := func(k string) string {
		v, err := node.GetKey(k)
		if err != nil {
			return ""
		}
		s, err := v.GetString()
		if err != nil {
			return ""
		}
		return s
	}
	return plane{
		name: str("name"), image: str("image"), tier: str("tier"),
		model: str("model"), pilot: str("pilot"), laser: str("laser"),
	}
}

// clean keeps a field from breaking a line: no "|" and no line break. The
// planes realm's names and URLs have none; this is a guard, not a filter.
func clean(s string) string {
	return strings.NewReplacer("|", " ", "\n", " ", "\r", " ").Replace(s)
}

// Render shows the listings on gnoweb.
func Render(_ string) string {
	var b strings.Builder
	b.WriteString("# gnofly planes market\n\n")
	b.WriteString("Planes of [gnofly](https://gnofly.xyz) for sale. A listed plane is held by this realm until it is bought or the listing is cancelled. ")
	b.WriteString("Each sale pays the planes realm's royalty to the gnofly treasury, the rest to the seller.\n\n")
	if paused {
		b.WriteString("New listings are paused: listed planes can still be bought or cancelled.\n\n")
	}
	if listings.Size() == 0 {
		b.WriteString("No plane is for sale.\n")
		return b.String()
	}
	b.WriteString("| Plane | Tier | Price | Seller |\n|---|---|---|---|\n")
	listings.Iterate("", "", func(k string, v any) bool {
		id, _ := strconv.Atoi(k)
		l := v.(*listing)
		p := planeInfo(id)
		b.WriteString("| [#" + k + " " + p.name + "](https://gnofly.xyz/nft/collections/planes/" + strconv.Itoa(id) + ") | " +
			p.tier + " | " + gnot(l.price) + " | " + l.seller.String() + " |\n")
		return false
	})
	return b.String()
}

// gnot writes ugnot as GNOT: 1000000 is "1 GNOT", 1500000 "1.5 GNOT".
func gnot(ugnot int64) string {
	whole, frac := ugnot/1_000_000, ugnot%1_000_000
	if frac == 0 {
		return strconv.FormatInt(whole, 10) + " GNOT"
	}
	f := strings.TrimRight(strconv.FormatInt(frac+1_000_000, 10)[1:], "0")
	return strconv.FormatInt(whole, 10) + "." + f + " GNOT"
}

// Address is this realm's address: the one sellers approve on the planes
// realm, and the owner of every listed plane.
func Address() address { return self }

package gnofly

import "gno.land/r/g1t2kg2vtr3fukg43eujkn6x53gfdyakhngt4sfd/gnofly/game/v0"

// The market keeps no roles of its own: its admins are the game realm's,
// asked again at every call, as the planes and skins realms do.

// authority is the one question this realm asks about roles.
type authority interface {
	IsAdmin(addr address) bool
}

// gameRoles answers with the roles of the game realm.
type gameRoles struct{}

func (gameRoles) IsAdmin(addr address) bool { return game.IsAdmin(addr) }

// roles is the authority of this realm. It is a variable only so that the
// tests can answer for the game realm, which has no admin under `gno test`.
var roles authority = gameRoles{}

// callerOf returns the verified caller of a crossing function; rlm must be
// its live cur.
func callerOf(_ int, rlm realm) address {
	if !rlm.IsCurrent() {
		panic(errSpoofedRealm)
	}
	return rlm.Previous().Address()
}

// userOf returns the caller, who must be a wallet calling directly: never a
// realm, so that no contract can act in a user's name or wrap a purchase.
func userOf(_ int, rlm realm) address {
	caller := callerOf(0, rlm)
	if !rlm.Previous().IsUserCall() {
		panic(errNotUserCall)
	}
	return caller
}

// assertAdmin panics unless the caller is an admin of the game realm.
func assertAdmin(_ int, rlm realm) address {
	caller := callerOf(0, rlm)
	if !roles.IsAdmin(caller) {
		panic(errNotAdmin)
	}
	return caller
}
